INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x15a','MILESTONE','x15a','curation:0030_0493x15_x18_mobile_solids');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x15a','0493x15a','x15a','0493x15a','solides mobiles / FSI','Audit du bilan de force du chi-solid fixe','Instrumente le budget de force/réaction du piston chi fixe et établit la fermeture mécanique avant l’étude de perméabilité.','DIAGNOSTIC','MOBILE_SOLID','REVIEW: bilan mécanique exploitable; imperméabilité non encore établie.','B','2026-09-12',NULL,NULL,'Précurseur direct des mesures x15b/x15c.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x15b','MILESTONE','x15b','curation:0030_0493x15_x18_mobile_solids');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x15b','0493x15b','x15b','0493x15b','solides mobiles / FSI','Décomposition exacte chiVP/Brinkman','Sépare exactement les contributions Brinkman et chiVP; montre qu’une fermeture du budget mécanique peut coexister avec un solide poreux.','DIAGNOSTIC','MOBILE_SOLID','Résultat mécanique validé; ne constitue pas une fermeture matérielle imperméable.','B','2026-09-12',NULL,NULL,'À faible alpha, la réaction est dominée par chiVP (~94%).','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

