INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x15c','0493x15c','x15c','0493x15c','solides mobiles / FSI','Mesure directe de perméabilité du chi-solid','Mesure les crossings à travers un slab et démontre que mean+chiVP reste poreux malgré une bonne fermeture de force.','DIAGNOSTIC','MOBILE_SOLID','PASS comme diagnostic de perméabilité; résultat physique: paroi volumique poreuse.','A','2026-09-12',NULL,NULL,'Summary exact archivé.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

