INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x15e','0493x15e','x15e','0493x15e','solides mobiles / FSI','Qualification de la chaîne historique forte','Avec mean_outward_bath, alpha=800000, chiVP=0.25 et exclusion initiale, obtient zéro crossing mesuré sur le slab.','QUALIFICATION','MOBILE_SOLID','PASS pour la chaîne historique statique; mécanisme non retenu comme fermeture mobile finale.','A','2026-09-12',NULL,NULL,'Summary exact archivé; l’imperméabilité dépend fortement du bath orienté.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

