INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x15f','0493x15f','x15f','0493x15f','solides mobiles / FSI','Ablation sans outward_bath','Retire outward_bath à forte pénalisation et fait réapparaître un flux de crossings très important.','ABLATION','MOBILE_SOLID','PASS comme ablation discriminante; direction rejetée pour un solide matériel mobile.','A','2026-09-12',NULL,NULL,'Summary exact archivé; établit le rôle dominant du bath post-pénétration.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

