INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x16b','0493x16b','x16b','0493x16b','solides mobiles / FSI','Charge solide spatiale exacte','Ajoute Delta p_s(c)=-Delta p_f(c) par cellule et la projection générique de cette charge vers les degrés de liberté du solide.','CODE','MOBILE_SOLID','Infrastructure de charge retenue; base du couplage mécanique ultérieur.','A','2026-09-12',NULL,NULL,'Package exact archivé.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

