INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x16c','0493x16c','x16c','0493x16c','solides mobiles / FSI','Inventaire du fluide fictif dans le solide','Ajoute un diagnostic de masse/moment/vitesse relative du fluide fictif afin d’attribuer les défauts du chi-solid mobile.','DIAGNOSTIC','MOBILE_SOLID','INFORMATIONAL; diagnostic de qualification, non physique nécessaire au chemin normal.','B','2026-09-12',NULL,NULL,'Devient opt-in/obsolète pour les géométries lagrangiennes avec x18d.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

