INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x16d','0493x16d','x16d','0493x16d','solides mobiles / FSI','Test galiléen du masque chi mobile','Montre que les sauts du masque binaire capturent brutalement des particules et corrèlent fortement masse fictive et pics d’impulsion.','QUALIFICATION','MOBILE_SOLID','REVIEW/FAIL comme invariance galiléenne du remapping binaire; résultat causal retenu.','A','2026-09-12',NULL,NULL,'Delta M_fict ~+639 aux shifts; RMS impulsion ~430.5 aux shifts contre ~35.7 hors shifts.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

