INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x16e','0493x16e','x16e','0493x16e','solides mobiles / FSI','Rasterisation subcellulaire CUDA résidente','Teste une représentation subcellulaire résidente pour adoucir les changements de support de la géométrie mobile.','CODE','MOBILE_SOLID','REVIEW; améliore la représentation mais ne résout pas le principe de capture/remapping.','B','2026-09-12',NULL,NULL,'Étape de la branche x16d--x16i finalement abandonnée comme mécanisme final.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

