INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x16f','0493x16f','x16f','0493x16f','solides mobiles / FSI','Synchronisation temporelle post-stream','Replace la mise à jour géométrique au niveau temporel post-stream correct pour tester l’hypothèse d’un décalage n/n+1.','EXPERIMENT','MOBILE_SOLID','Résultat négatif: effet faible; le défaut principal n’est pas la synchronisation temporelle.','A','2026-09-12',NULL,NULL,'Tentative infructueuse conservée comme enseignement.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

