INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x16g','0493x16g','x16g','0493x16g','solides mobiles / FSI','Neutralisation du bath lors de la capture','Neutralise l’impulsion collective de bath sur les particules nouvellement capturées par le masque.','EXPERIMENT','MOBILE_SOLID','Résultat négatif: le pic est déplacé au pas suivant; corriger la vitesse seule est insuffisant.','A','2026-09-12',NULL,NULL,'Tentative infructueuse conservée.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

