INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x16h','0493x16h','x16h','0493x16h','solides mobiles / FSI','Réinjection spatiale des particules capturées','Replace les particules capturées du côté fluide; réduit les pics mais provoque une déplétion artificielle du nouveau support solide.','EXPERIMENT','MOBILE_SOLID','REVIEW/REJECTED_DIRECTION: gain local mais remapping trop brutal.','A','2026-09-12',NULL,NULL,'Réduction ~70% du pic d’impulsion et ~95% du bath, au prix d’une forte déplétion.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

