INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x17c','0493x17c','x17c','0493x17c','solides mobiles / FSI','Première mécanique de membrane lagrangienne','Fait des noeuds x17a des DOF matériels avec ressorts d’arêtes, pénalité d’aire, amortissement interne et distribution nodale des impulsions.','CODE','FSI','Couplage FSI fonctionnel; mécanique structurelle minimale non revendiquée comme modèle de solide détaillé.','A','2026-09-14',NULL,NULL,'Package exact archivé.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x17d','MILESTONE','x17d','curation:0030_0493x15_x18_mobile_solids');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x17d','0493x17d','x17d','0493x17d','solides mobiles / FSI','Membrane ancrée / plaque flexible de démonstration','Ajoute ancrages géométriques puis explore flexion et cohérence transverse pour obtenir une déformation visible sous charge fluide.','EXPERIMENT','FSI','HISTORICAL/REVIEW: transfert FSI démontré, mais tuning structural abandonné après rigidités excessives ou repliements.','A','2026-09-14',NULL,NULL,'Les fix mécaniques ultérieurs restent preuves sous x17d, sauf fix2 promu séparément.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x17d-fix2','MILESTONE','x17d-fix2','curation:0030_0493x15_x18_mobile_solids');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x17d-fix2','0493x17d-fix2','x17d-fix2','0493x17d-fix2','solides mobiles / FSI','Couverture complète des particules par le collisionneur x17a','Supprime un plafond historique de lancement de 4096 blocs qui limitait le traitement à 1048576 particules sur les grands cas.','FIX','MOBILE_SOLID','Correctif de couverture nécessaire; conservé comme jalon de correction de calcul.','A','2026-09-14',NULL,NULL,'Package exact archivé.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x18a','MILESTONE','x18a','curation:0030_0493x15_x18_mobile_solids');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x18a','0493x18a','x18a','0493x18a','solides mobiles / FSI','Volet rigide articulé 1-DOF','Ajoute hinged_plate_2d: contour rigide de faible épaisseur, charnière z fixe, dynamique I*theta_ddot=tau_hydro+tau_g-C*omega et couple issu des impacts x17a.','CODE','FSI','Démonstrateur courant; runs transverse-flow propres sur les audits de pénétration disponibles.','A','2026-09-14',NULL,NULL,'Sortie physique chi_hinged_plate_0493x18a.csv; package et CSV archivés.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x18a-fix2','MILESTONE','x18a-fix2','curation:0030_0493x15_x18_mobile_solids');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x18a-fix2','0493x18a-fix2','x18a-fix2','0493x18a-fix2','solides mobiles / FSI','Initialisation du fluide cohérente avec l’angle du volet','Corrige le trou de fluide vertical laissé par la déactivation chi initiale lorsque le contour lagrangien est initialement tourné.','FIX','FSI','Correctif d’initialisation retenu; aucun changement C++/CUDA.','A','2026-09-14',NULL,NULL,'Désactive la déactivation Eulerienne initiale et exclut les particules dans le volet effectivement tourné.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x18b','MILESTONE','x18b','curation:0030_0493x15_x18_mobile_solids');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x18b','0493x18b','x18b','0493x18b','solides mobiles / FSI','Chute du volet dans un fluide au repos','Variante x18a: volet initialement relevé, gravité, Ux=0 et sweep de densité fluide en scalant masse particulaire et kBT au même facteur.','RUNNER','FSI','Démonstrateur courant; audit cadence 1 propre sur 254 échantillons du cas gaz documenté.','A','2026-09-14',NULL,NULL,'Gas/liquid sont des labels de densité dans le même modèle MPCD, pas des EOS distinctes.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x18d','MILESTONE','x18d','curation:0030_0493x15_x18_mobile_solids');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x18d','0493x18d','x18d','0493x18d','solides mobiles / FSI','Nettoyage global du chemin normal des solides mobiles','Rend les diagnostics de qualification lourds opt-in via chiSolidQualificationDiagnosticsEnable=false par défaut et conserve seulement physique + résultats scientifiques dans le chemin normal.','OPTIMIZATION','MOBILE_SOLID','CURRENT/PENDING_LOCAL_CUDA_BUILD_AND_BENCHMARK; ne pas marquer PASS tant que la validation locale autoritaire n’est pas rapportée.','A','2026-09-14',NULL,NULL,'x18c spécialisé est explicitement rejeté/non canonique; x18d est global à tous les modèles de solides mobiles.','Info/inputs/historical/README_0493X15_X18_MOBILE_SOLIDS_20260915.md',NULL);

